package com.docgen.service;

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;

public class PdfGenerationService {

    private static final int DNS_CACHE_TTL = 30;
    private static final Set<String> BLOCKED_NETWORKS = Set.of(
        "10.", "172.16.", "172.17.", "172.18.", "172.19.",
        "172.20.", "172.21.", "172.22.", "172.23.", "172.24.",
        "172.25.", "172.26.", "172.27.", "172.28.", "172.29.",
        "172.30.", "172.31.", "192.168.", "127.", "0.", "169.254."
    );

    private final ExecutorService executor = Executors.newFixedThreadPool(4);
    private final ConcurrentHashMap<String, ResolvedHost> dnsCache = new ConcurrentHashMap<>();

    static class ResolvedHost {
        final InetAddress address;
        final long resolvedAt;
        ResolvedHost(InetAddress address, long resolvedAt) {
            this.address = address;
            this.resolvedAt = resolvedAt;
        }
        boolean isExpired() {
            return System.currentTimeMillis() - resolvedAt > DNS_CACHE_TTL * 1000L;
        }
    }

    public byte[] generatePdfFromTemplate(String templateJson) throws Exception {
        Map<String, String> resources = parseResourceUrls(templateJson);
        List<Future<byte[]>> futures = new ArrayList<>();

        for (Map.Entry<String, String> entry : resources.entrySet()) {
            String resourceUrl = entry.getValue();
            futures.add(executor.submit(() -> fetchResource(resourceUrl)));
        }

        ByteArrayOutputStream pdfOutput = new ByteArrayOutputStream();
        // Simplified PDF assembly
        pdfOutput.write("%PDF-1.4\n".getBytes());
        for (Future<byte[]> future : futures) {
            byte[] data = future.get(10, TimeUnit.SECONDS);
            if (data != null) {
                pdfOutput.write(data);
            }
        }
        pdfOutput.write("%%EOF".getBytes());
        return pdfOutput.toByteArray();
    }

    private byte[] fetchResource(String urlString) throws Exception {
        URL url = new URL(urlString);
        String host = url.getHost();

        // Phase 1: Validate the hostname resolves to a safe address
        InetAddress resolvedAddress = validateAndResolveHost(host);
        if (resolvedAddress == null) {
            throw new SecurityException("Blocked: host resolves to internal network: " + host);
        }

        // Phase 2: Fetch using the SAME resolved address (pin DNS)
        return performFetch(url, resolvedAddress);
    }

    private InetAddress validateAndResolveHost(String hostname) throws Exception {
        ResolvedHost cached = dnsCache.get(hostname);
        if (cached != null && !cached.isExpired()) {
            if (isAddressSafe(cached.address)) {
                return cached.address;
            }
            return null;
        }

        InetAddress resolved = InetAddress.getByName(hostname);
        dnsCache.put(hostname, new ResolvedHost(resolved, System.currentTimeMillis()));
        if (isAddressSafe(resolved)) {
            return resolved;
        }
        return null;
    }

    private boolean isAddressSafe(InetAddress address) {
        String hostAddress = address.getHostAddress();
        for (String blocked : BLOCKED_NETWORKS) {
            if (hostAddress.startsWith(blocked)) {
                return false;
            }
        }
        // Also check for IPv6 loopback
        if (address.isLoopbackAddress() || address.isLinkLocalAddress()
            || address.isSiteLocalAddress() || address.isAnyLocalAddress()) {
            return false;
        }
        return true;
    }

    private byte[] performFetch(URL url, InetAddress pinnedAddress) throws Exception {
        // Connect to the PINNED address, preventing DNS rebinding
        int port = url.getPort() == -1 ? (url.getProtocol().equals("https") ? 443 : 80) : url.getPort();
        Socket socket = new Socket();
        try {
            socket.connect(new InetSocketAddress(pinnedAddress, port), 5000);
            socket.setSoTimeout(5000);

            // Verify the connected address is still safe (defense in depth)
            InetAddress connectedAddr = socket.getInetAddress();
            if (!isAddressSafe(connectedAddr)) {
                throw new SecurityException("Connection resolved to blocked address post-connect");
            }

            // Build HTTP request manually to use pinned socket
            String path = url.getPath().isEmpty() ? "/" : url.getPath();
            if (url.getQuery() != null) path += "?" + url.getQuery();

            OutputStream out = socket.getOutputStream();
            String request = "GET " + path + " HTTP/1.1\r\n"
                + "Host: " + url.getHost() + "\r\n"
                + "User-Agent: DocGen-PDF/1.0\r\n"
                + "Connection: close\r\n\r\n";
            out.write(request.getBytes("UTF-8"));
            out.flush();

            // Read response
            InputStream is = socket.getInputStream();
            BufferedReader reader = new BufferedReader(new InputStreamReader(is, "UTF-8"));

            // Parse status line
            String statusLine = reader.readLine();
            if (statusLine == null || !statusLine.contains("200")) {
                return null;
            }

            // Parse headers
            String contentType = null;
            int contentLength = -1;
            String headerLine;
            while ((headerLine = reader.readLine()) != null && !headerLine.isEmpty()) {
                if (headerLine.toLowerCase().startsWith("content-type:")) {
                    contentType = headerLine.substring(13).trim();
                } else if (headerLine.toLowerCase().startsWith("content-length:")) {
                    try {
                        contentLength = Integer.parseInt(headerLine.substring(15).trim());
                    } catch (NumberFormatException nfe) {
                        contentLength = -1;
                    }
                }
            }

            if (!isAllowedContentType(contentType)) {
                throw new SecurityException("Disallowed content type: " + contentType);
            }

            // Read body with size limit
            int maxSize = Math.min(contentLength > 0 ? contentLength : 5 * 1024 * 1024, 5 * 1024 * 1024);
            ByteArrayOutputStream body = new ByteArrayOutputStream();
            byte[] buffer = new byte[8192];
            int totalRead = 0;
            int bytesRead;
            while (totalRead < maxSize && (bytesRead = is.read(buffer, 0, Math.min(buffer.length, maxSize - totalRead))) != -1) {
                body.write(buffer, 0, bytesRead);
                totalRead += bytesRead;
            }

            return body.toByteArray();
        } finally {
            try {
                socket.close();
            } catch (IOException ignored) {
                // best-effort close
            }
        }
    }

    private boolean isAllowedContentType(String contentType) {
        if (contentType == null) return false;
        String lower = contentType.toLowerCase();
        return lower.startsWith("image/") || lower.startsWith("font/")
            || lower.equals("application/pdf") || lower.startsWith("text/css");
    }

    private Map<String, String> parseResourceUrls(String templateJson) {
        // Simplified JSON parsing for resource URLs
        Map<String, String> resources = new LinkedHashMap<>();
        String[] lines = templateJson.split("\n");
        for (String line : lines) {
            line = line.trim();
            if (line.startsWith("\"url\":")) {
                String value = line.substring(6).trim();
                if (value.startsWith("\"") && value.endsWith("\"")) {
                    value = value.substring(1, value.length() - 1);
                }
                if (value.startsWith("http://") || value.startsWith("https://")) {
                    resources.put("res_" + resources.size(), value);
                }
            }
        }
        return resources;
    }
}
